container.literal_block:
from typing import Callable, Type
import pytorch_lightning as pl import torch as tr import torch.nn as nn import torch.nn.functional as F from torch.optim import Optimizer # type: ignore from torch.utils.data import DataLoader, TensorDataset
from hydra_zen.typing import Partial
__all__ = ["UniversalFuncModule", "single_layer_nn", "train_and_eval"]
def single_layer_nn(num_neurons: int) -> nn.Module: """y = sum(V sigmoid(X W + b))""" return nn.Sequential( nn.Linear(1, num_neurons), nn.Sigmoid(), nn.Linear(num_neurons, 1, bias=False), )
class UniversalFuncModule(pl.LightningModule): def __init__( self, model: nn.Module, optim: Partial[Optimizer], dataloader: Type[DataLoader], target_fn: Callable[[tr.Tensor], tr.Tensor], training_domain: tr.Tensor, ): super().__init__() self.optim = optim self.dataloader = dataloader self.training_domain = training_domain self.target_fn = target_fn
self.model = model
def forward(self, x): return self.model(x)
def configure_optimizers(self): # provide optimizer with model parameters return self.optim(self.parameters())
def training_step(self, batch, batch_idx): x, y = batch # compute |cos(x) - model(x)|^2 return F.mse_loss(self.model(x), y)
def train_dataloader(self): # generate dataset: x, cos(x) x = self.training_domain.reshape(-1, 1) y = self.target_fn(x) return self.dataloader(TensorDataset(x, y))
def train_and_eval( model: tr.nn.Module, optim: Partial[Optimizer], dataloader: Type[DataLoader], target_fn: Callable[[tr.Tensor], tr.Tensor], training_domain: tr.Tensor, lit_module: Type[UniversalFuncModule], trainer: pl.Trainer, ):
lit = lit_module( model=model, optim=optim, dataloader=dataloader, target_fn=target_fn, training_domain=training_domain, )
# train the model trainer.fit(lit)
# evaluate the model over the domain to assess the fit final_eval = lit(training_domain.reshape(-1, 1)) final_eval = final_eval.detach().cpu().numpy().ravel()
# return the final evaluation of our model: # a shape-(N,) numpy-array return final_eval

admonition.paragraph:
For the interested reader… In this toy-problem we are optimizing arbitrary-width universal function approximators to fit \cos{x}
                        on x \in [-2\pi, 2\pi].
                        In mathematical notation, we want to solve the following optimization problem:

admonition.math_block:
F(\vec{v}, \vec{w}, \vec{b}; x) &= \sum_{i=1}^{N}{v_{i}\sigma(x w_i + b_i)}

\vec{v}^*, \vec{w}^*, \vec{b}^* &= \operatorname*{arg\,min}_{\vec{v}, \vec{w}, \vec   {b}\in\mathbb{R}^{N}} \;  \|F(\vec{v}, \vec{w}, \vec{b}; x)\ - \cos{x}\|_{2}

x &\in [-2\pi, 2\pi]
